        /**
          * Forwarded to the host as `aria-label`. Defaults to Romanian "Subsol pagină".
         */
        "ariaLabel"?: string;
        /**
          * Contact block (email / phone / address). When undefined, the section is hidden. Pass an empty object to opt out of the Romanian defaults.
         */
